SIMPROC = {"p": None}


def sim_dir():
    return os.path.join(DATA_DIR, "simulator")


def _desktop_user():
    """(uid, gid, home, name) of the person at the desktop (the service often runs as root) - or of this program."""
    import pwd
    for d in sorted(glob.glob("/run/user/*")):
        try:
            uid = int(os.path.basename(d))
        except ValueError:
            continue
        if uid >= 1000 and (glob.glob(os.path.join(d, "wayland-*")) or os.path.exists(os.path.join(d, "bus"))):
            try:
                p = pwd.getpwuid(uid); return uid, p.pw_gid, p.pw_dir, p.pw_name
            except KeyError:
                continue
    p = pwd.getpwuid(os.getuid())
    return p.pw_uid, p.pw_gid, p.pw_dir, p.pw_name


def sim_install():
    """Unpack the simulator into <data>/simulator, add a menu entry and a desktop icon for the person at the Pi."""
    import base64, io
    d = sim_dir(); os.makedirs(d, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(SIM_ZIP_B64.split())))) as z:
        for n in z.namelist():
            if re.fullmatch(r"[A-Za-z0-9_.]+", n):
                with open(os.path.join(d, n), "wb") as f:
                    f.write(z.read(n))
    os.chmod(os.path.join(d, "motionwatch_simulator.py"), 0o755)
    icon = os.path.join(d, "simulator.png")
    try:
        import base64
        with open(icon, "wb") as f:
            f.write(base64.b64decode("".join(SIM_ICONS_PNG["simbasis"])))      # MoveEye Sim · Basis: the radar eye with the grey badge
    except Exception:
        pass
    entry = ("[Desktop Entry]\nType=Application\nName=MoveEye Sim · Basis\nComment=Test MoveEye without hardware\n"
             f"Exec={sys.executable} {os.path.join(d, 'motionwatch_simulator.py')}\nPath={d}\nIcon={icon}\nTerminal=false\nCategories=Utility;\n")
    uid, gid, home, name = _desktop_user()
    made = []
    for folder in (os.path.join(home, ".local", "share", "applications"), os.path.join(home, "Desktop"), os.path.join(home, "Schreibtisch")):
        if folder.endswith(("Desktop", "Schreibtisch")) and not os.path.isdir(folder):
            continue
        try:
            os.makedirs(folder, exist_ok=True)
            p = os.path.join(folder, "motionwatch-simulator.desktop")
            with open(p, "w") as f:
                f.write(entry)
            os.chmod(p, 0o755)
            if os.getuid() == 0:
                os.chown(p, uid, gid)
            made.append(p)
        except OSError:
            continue
    if os.getuid() == 0:
        for root_, _ds, fs in os.walk(d):
            for x in fs + [""]:
                try:
                    os.chown(os.path.join(root_, x) if x else root_, uid, gid)
                except OSError:
                    pass
    log_event("sys", f"Simulator installed in {d}" + (f" (menu / desktop icon for {name})" if made else ""))
    return True, d


def sim_running():
    p = SIMPROC["p"]
    return p is not None and p.poll() is None


def sim_start():
    """Start the simulator on this Pi: with its window on the desktop when somebody is logged in, otherwise without window."""
    if sim_running():
        return True, ""
    exe = os.path.join(sim_dir(), "motionwatch_simulator.py")
    if not os.path.isfile(exe):
        ok, _ = sim_install()
    else:
        sim_autoupdate()
    uid, gid, home, name = _desktop_user()
    env = dict(os.environ)
    run = f"/run/user/{uid}"
    way = sorted(glob.glob(os.path.join(run, "wayland-*")))
    window = bool(way) or os.path.exists("/tmp/.X11-unix/X0") or bool(os.environ.get("DISPLAY"))
    if window:
        env.update(XDG_RUNTIME_DIR=run, HOME=home, USER=name)
        if way:
            env["WAYLAND_DISPLAY"] = os.path.basename([w for w in way if not w.endswith(".lock")][0]) if [w for w in way if not w.endswith(".lock")] else "wayland-0"
        env.setdefault("DISPLAY", ":0")
    cmd = [sys.executable, exe] + ([] if window else ["--no-window"])
    kw = {"user": uid, "group": gid} if os.getuid() == 0 and uid != 0 else {}
    try:
        SIMPROC["p"] = subprocess.Popen(cmd, cwd=sim_dir(), env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                        start_new_session=True, **kw)
    except (OSError, ValueError) as e:
        return False, str(e)[:120]
    CFG["sim_url"] = "http://127.0.0.1:8765"; save_settings()
    log_event("sys", "Simulator started on this device" + (" (with window)" if window else " (without window)"))
    return True, ""


def sim_stop():
    p = SIMPROC["p"]
    if p is not None and p.poll() is None:
        try:
            os.killpg(p.pid, signal.SIGTERM)
        except OSError:
            p.terminate()
        log_event("sys", "Simulator stopped")
    SIMPROC["p"] = None
    return True, ""


def sens_has_pir():
    return CFG["sens_on"] and any(x["kind"] == "pir" and x["src"] for x in CFG["sensors"])


def eco_fps_now():
    f = max(1.0, float(CFG["eco_fps"]))
    return 1.0 if CFG["eco_pir"] and sens_has_pir() else f


def sms_numbers():
    return [n for n in re.split(r"[,; ]+", CFG["sms_numbers"]) if _PHONE_RE.match(n)][:5]


def _sms_mmcli(num, text):
    exe = shutil.which("mmcli")
    if not exe:
        return False, "mmcli missing (sudo apt install modemmanager)"
    rc, out, err = _run([exe, "-L"], 15)
    m = re.search(r"/Modem/(\d+)", out or "")
    if not m:
        return False, "no modem found (stick plugged in? mmcli -L)"
    safe = text.replace("'", "’").replace("\\", "/")
    for pre in ([], ["sudo", "-n"]):
        rc, out, err = _run(pre + [exe, "-m", m.group(1), f"--messaging-create-sms=text='{safe}',number='{num}'"], 20)
        sm = re.search(r"/SMS/(\d+)", out or "")
        if rc == 0 and sm:
            rc2, out2, err2 = _run(pre + [exe, "-s", sm.group(1), "--send"], 60)
            if rc2 == 0:
                return True, ""
            err = err2 or out2
    return False, ("mmcli: " + (err or out or "error").strip())[:160]


def _sms_at(num, text):
    import termios
    port = CFG["sms_port"].strip() or "/dev/ttyUSB2"
    if not os.path.exists(port):
        return False, f"{port} not found"
    try:
        fd = os.open(port, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
    except OSError as e:
        return False, f"{port}: {e.strerror} (in use by ModemManager?)"
    try:
        a = termios.tcgetattr(fd)
        a[4] = a[5] = termios.B115200; a[2] |= termios.CLOCAL | termios.CREAD; a[3] = 0; a[1] = 0; a[0] = 0
        termios.tcsetattr(fd, termios.TCSANOW, a)

        def cmd(b, wait=2.0, until=(b"OK", b"ERROR", b">")):
            os.write(fd, b)
            buf = b""; end = time.time() + wait
            while time.time() < end:
                try:
                    c = os.read(fd, 256)
                    buf += c
                    if any(u in buf for u in until):
                        break
                except BlockingIOError:
                    time.sleep(0.05)
            return buf
        if b"OK" not in cmd(b"AT\r"):
            return False, "the modem does not answer (wrong port?)"
        cmd(b"AT+CMGF=1\r")
        cmd(b'AT+CSCS="GSM"\r')
        if b">" not in cmd(f'AT+CMGS="{num}"\r'.encode(), 5):
            return False, "the modem refuses the SMS"
        for a_, b_ in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("Ä", "Ae"), ("Ö", "Oe"), ("Ü", "Ue"), ("ß", "ss"), ("–", "-"), ("’", "'"), ("«", '"'), ("»", '"')):
            text = text.replace(a_, b_)
        txt = text.encode("ascii", "replace")[:160]
        r = cmd(txt + b"\x1a", 60, (b"+CMGS", b"ERROR"))
        return (True, "") if b"+CMGS" in r else (False, "SMS not sent (credit / network?)")
    finally:
        os.close(fd)


def _sms_hilink(num, text):
    import http.cookiejar
    base = "http://" + (CFG["sms_hilink"].strip() or "192.168.8.1")
    op = urllib.request.build_opener(urllib.request.ProxyHandler({}), urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
    try:
        with op.open(base + "/api/webserver/SesTokInfo", timeout=8) as r:
            x = r.read().decode(errors="replace")
        ses = re.search(r"<SesInfo>(.*?)</SesInfo>", x); tok = re.search(r"<TokInfo>(.*?)</TokInfo>", x)
        if not tok:
            return False, "HiLink stick not found (address?)"
        from xml.sax.saxutils import escape
        body_ = (f"<?xml version='1.0' encoding='UTF-8'?><request><Index>-1</Index><Phones><Phone>{escape(num)}</Phone></Phones><Sca></Sca>"
                 f"<Content>{escape(text[:300])}</Content><Length>{len(text[:300])}</Length><Reserved>1</Reserved>"
                 f"<Date>{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}</Date></request>").encode()
        h = {"__RequestVerificationToken": tok.group(1), "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"}
        if ses:
            h["Cookie"] = ses.group(1)
        with op.open(urllib.request.Request(base + "/api/sms/send-sms", data=body_, headers=h), timeout=20) as r:
            ans = r.read().decode(errors="replace")
        return (True, "") if "<response>OK</response>" in ans else (False, "HiLink: " + (re.search(r"<code>(\d+)</code>", ans).group(1) if "<code>" in ans else "error"))
    except Exception as e:
        return False, f"HiLink: {str(e)[:120]}"


def sms_send(text, force=False):
    """Send `text` to all numbers. force=True (test) ignores the limits."""
    nums = sms_numbers()
    if not nums:
        return False, "no phone number set"
    now = time.time()
    SMS["sent"] = [t for t in SMS["sent"] if now - t < 86400]
    if not force:
        if now - SMS["last"] < float(CFG["sms_pause"]) * 60:
            return False, "pause between two SMS"
        if len(SMS["sent"]) >= int(CFG["sms_day_max"]):
            return False, "daily limit reached"
    mode = CFG["sms_mode"]
    order = {"mmcli": [_sms_mmcli], "at": [_sms_at], "hilink": [_sms_hilink]}.get(mode, [_sms_mmcli, _sms_hilink, _sms_at])
    text = re.sub(r"\s+", " ", text).strip()[:300]
    errs = []
    ok_any = False
    for n in nums:
        ok = False
        for f in order:
            ok, err = f(n, text)
            if ok:
                break
            errs.append(err)
        ok_any = ok_any or ok
    SMS["last"] = now
    if ok_any:
        SMS["sent"].append(now)
    SMS["status"] = (f"✓ {datetime.now().strftime('%H:%M')}" if ok_any else "⚠ " + (errs[-1] if errs else "error"))[:160]
    log_event("web", ("SMS sent" if ok_any else "SMS failed: " + (errs[-1] if errs else "error"))[:200])
    return ok_any, "" if ok_any else (errs[-1] if errs else "error")

